async function liveApi(url,options={}){
  // Render Free can take longer than 7.5 seconds to start after idle.
  const timeout=new AbortController(),timer=setTimeout(()=>timeout.abort(),60000);
  try{
    let response;
    try{
      response=await fetch(ONLINE_ORIGIN+url,{method:options.body?'POST':'GET',mode:'cors',cache:'no-store',signal:timeout.signal,
        headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.auth?{'Authorization':'Bearer '+adminBearer}:{})},
        ...(options.body?{body:JSON.stringify(options.body)}:{})});
    }catch(e){
      if(e&&e.name==='AbortError')throw new Error('サーバーが応答しませんでした。しばらくしてから再試行してね');
      throw new Error('サーバーに接続できません。通信環境とRenderの状態を確認してね');
    }
    const raw=await response.text();
    let data;
    try{data=JSON.parse(raw)}catch{data=null}
    if(response.status===404 && !data?.error)
      throw new Error('サーバーが旧バージョンのままです。Renderの更新完了後に再試行してね');
    if(!response.ok)throw new Error(data?.error||('サーバーエラー HTTP '+response.status));
    if(!data||typeof data!=='object')throw new Error('サーバーから正しいデータが返りませんでした');
    return data;

